var s=`0226-sardinhas-assadas`;var a=`world-0226`;var n=`PT`;var t=`southern-europe`;var r=4;var o=29;var d={en:`Sardinhas Assadas`,ua:`Смажені сардини`};var l={en:`A traditional Portugal dish made with sardine, sea salt, lemon, parsley. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Португалія. Основні інгредієнти: сардина, морська сіль, лимон, петрушка. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 15 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 15 хвилин.`,t:[`marinating`],m:15,i:[[`sardine`,800,`g`],[`extra-virgin-olive-oil`,45,`ml`],[`sea-salt`,8,`g`]]},{en:`Grill over medium-high heat for about 12 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 12 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:12,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`lemon`,2,`pcs`],[`parsley`,15,`g`]]}];var u={slug:s,id:a,country:`PT`,region:t,servings:4,minutes:29,title:d,text:l,steps:g};export{n as country,u as default,a as id,o as minutes,t as region,r as servings,s as slug,g as steps,l as text,d as title};